      if (result.objects_opened >= cap) { result.more = true; break; }
      const day = eligible.map(nextOf).sort().reverse()[0]!;
      journal = { version: 1, tenant, id: crypto.randomUUID().replace(/-/g, ''), day, window_days: window, phase: 'preparing',
