// ---------------------------------------------------------------------------
// Historical rows: the warehouse's past, applied to a shopper as actions that
// arrived late.
//
// A row names a shopper one of three ways: the site's account id (hashed here
// to the shopper id, so the raw id is read once and stored never), a shopper
// id the site already computed, or a visitor id. A visitor id that was linked
// resolves to its person; one that was not is applied to that browser's own
// profile, which is still right: it is the same browser.
//
// A row's product attributes become touches exactly as a live event's would,
// through the sanitizer and the registry, so an imported purchase of a Tabby
// scores `line: Tabby` at weight 5 the way a live purchase does. The weight is
// then discounted by everything that has decayed between the row's time and the
// present (identityMerge.applyHistorical), which is what "arriving late" means.
//
// Rows are grouped by shopper and applied in one write per shopper. Bounded at
// 1000 rows per request: a warehouse export is a stream of requests, not one.
// ---------------------------------------------------------------------------

import { z } from 'zod';
import type { Env } from '@/types/env';
import type { TenantId } from '@/tenancy/tenant';
import { shopperObject } from '@/tenancy/objects';
import { resolveReflexConfig, resolveSurface } from '@/demos/registry';
import { SessionManager } from '@/services/SessionManager';
import { extractTouches, sanitizeEventAttributes, tick, type ReflexConfig, type Touch } from '@/reflex/core';
import { applyHistorical } from '@/reflex/identityMerge';
import { IdentityStore } from '@/identity/store';
import { isSalted, isShopperId, shopperIdFor } from '@/identity/shopperId';

export const MAX_ROWS = 1000;

const timeSchema = z.union([z.number().finite(), z.string().min(4)]).transform((v, ctx) => {
  const ms = typeof v === 'number' ? (v < 1e11 ? v * 1000 : v) : Date.parse(v);
  if (!Number.isFinite(ms)) { ctx.addIssue({ code: 'custom', message: 'unparseable time' }); return z.NEVER; }
  return ms;
});

export const historyRowSchema = z.object({
  accountId: z.string().trim().min(1).max(200).optional(),
  shopperId: z.string().trim().min(1).max(64).optional(),
  visitorId: z.string().trim().min(1).max(200).optional(),
  action: z.string().trim().min(1).max(64),
  at: timeSchema,
  product: z.record(z.string(), z.unknown()).optional(),
  attributes: z.record(z.string(), z.unknown()).optional(),
}).refine((r) => r.accountId || r.shopperId || r.visitorId, { message: 'a row needs accountId, shopperId or visitorId' });

export type HistoryRow = z.infer<typeof historyRowSchema>;

export interface HistoryReport {
  received: number;
  applied: number;
  shoppers: number;
  /** Rows that named nobody we could resolve, or carried no registry touch. Index into the request. */
  skipped: Array<{ index: number; reason: string }>;
  perShopper: Array<{ shopperId: string; rows: number; audiences: string[]; created: boolean }>;
}

/**
 * CSV with a header row. Columns: account_id | shopper_id | visitor_id, action,
 * at, then any product attribute the registry can read (line, category, …).
 * Quoted fields are honoured; that is the whole grammar.
 */
export function parseHistoryCsv(text: string): Array<Record<string, unknown>> {
  const lines = text.split(/\r?\n/).filter((l) => l.trim() !== '');
  if (lines.length < 2) return [];
  const split = (line: string): string[] => {
    const out: string[] = []; let cur = ''; let q = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (q) { if (ch === '"' && line[i + 1] === '"') { cur += '"'; i++; } else if (ch === '"') q = false; else cur += ch; }
      else if (ch === '"') q = true; else if (ch === ',') { out.push(cur); cur = ''; } else cur += ch;
    }
    out.push(cur);
    return out.map((s) => s.trim());
  };
  const header = split(lines[0]).map((h) => h.toLowerCase());
  const known: Record<string, string> = { account_id: 'accountId', accountid: 'accountId', shopper_id: 'shopperId', shopperid: 'shopperId', visitor_id: 'visitorId', visitorid: 'visitorId', action: 'action', at: 'at', time: 'at', timestamp: 'at' };
  return lines.slice(1).map((line) => {
    const cells = split(line);
    const row: Record<string, unknown> = {}; const product: Record<string, unknown> = {};
    header.forEach((h, i) => {
      const v = cells[i] ?? '';
      if (v === '') return;
      const k = known[h];
      if (k) row[k] = k === 'at' && /^\d+(\.\d+)?$/.test(v) ? Number(v) : v;
      else product[h] = /^-?\d+(\.\d+)?$/.test(v) ? Number(v) : v;
    });
    if (Object.keys(product).length) row.product = product;
    return row;
  });
}

function touchesOf(row: HistoryRow, cfg: ReflexConfig): Touch[] {
  const attrs = { ...(row.product ?? {}), ...(row.attributes ?? {}) };
  return extractTouches(sanitizeEventAttributes(attrs, cfg), cfg);
}

/** Apply a batch. Rows are validated by the caller; this resolves, groups and writes. */
export async function applyHistory(env: Env, tenant: TenantId, rows: HistoryRow[], now = Date.now()): Promise<HistoryReport> {
  const store = new IdentityStore(env.SESSIONS as never, tenant);
  const cfg = await resolveReflexConfig(env, resolveSurface(null));
  const report: HistoryReport = { received: rows.length, applied: 0, shoppers: 0, skipped: [], perShopper: [] };

  // Resolve every row to a target id, then group.
  const groups = new Map<string, Array<{ action: string; at: number; touches: Touch[]; index: number }>>();
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    let target: string | null = null;
    if (r.shopperId) {
      if (!isShopperId(r.shopperId)) { report.skipped.push({ index: i, reason: 'shopperId is not a shopper id' }); continue; }
      target = r.shopperId;
    } else if (r.accountId) {
      target = await shopperIdFor(env, tenant, r.accountId);
    } else if (r.visitorId) {
      target = (await store.resolveVisitor(r.visitorId)) ?? r.visitorId;
    }
    if (!target) { report.skipped.push({ index: i, reason: 'no shopper' }); continue; }
    if ((cfg.weights[r.action] ?? 0) <= 0) { report.skipped.push({ index: i, reason: `action "${r.action}" has no weight` }); continue; }
    const touches = touchesOf(r, cfg);
    if (touches.length === 0) { report.skipped.push({ index: i, reason: 'no registry attribute on the row' }); continue; }
    const g = groups.get(target) ?? [];
    g.push({ action: r.action, at: r.at, touches, index: i });
    groups.set(target, g);
  }

  const onObjectHost = (env.REFLEX_HOST ?? 'session') === 'do';
  const sm = new SessionManager(env, { tenant });

  for (const [target, batch] of groups) {
    const person = isShopperId(target);
    const latestAt = Math.max(...batch.map((b) => b.at));
    if (onObjectHost) {
      const stub = shopperObject(env.SHOPPER_REFLEX, target, tenant);
      const res = (await (await stub.fetch('https://shopper-reflex/identity/import', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ shopperId: target, now, rows: batch.map(({ action, at, touches }) => ({ action, at, touches })) }),
      })).json()) as { audiences?: string[] };
      report.perShopper.push({ shopperId: target, rows: batch.length, audiences: res.audiences ?? [], created: false });
    } else {
      const sid = await sm.resolveSessionIdByUserId(target);
      const existing = sid ? (await sm.resolveRecord(sid)).data : null;
      let state = existing?.reflex ?? null;
      for (const b of batch) state = applyHistorical(state, { action: b.action, touches: b.touches }, b.at, cfg);
      const evaluated = tick(state, now, cfg);
      const written = await sm.applyImport({
        userId: target, reflex: evaluated.state, now,
        identity: person ? { shopperId: target, linkedAt: now } : undefined,
      });
      report.perShopper.push({ shopperId: target, rows: batch.length, audiences: evaluated.state.audiences, created: written.created });
    }
    if (person) await store.noteHistory(target, batch.length, latestAt, isSalted(env), now);
    report.applied += batch.length;
  }
  report.shoppers = groups.size;
  return report;
}
"}

{"path":"src/learn/fan.ts","sha256":"13d090c8e11c42916b01ec81e4c5b7ccc2cbedc93ee97fe8f4be4d1a25150496","content":"// src/learn/fan.ts
// The three fan-ins the learning loop needs, each a no-op without its binding
// and none of them able to throw: served decisions into the visitor's ring,
// exposures into the slot's statistics object, and an outcome into the ring,
// which attributes it and forwards the credits itself.

import type { Env } from '@/types/env';
import type { DecisionRecord } from '@/content/types';
import type { OutcomeRecord } from '@/ledger/records';
import type { AttributionPolicy, RingEntry } from './policy';
import type { StatsConfig } from './stats';
import type { RewardType } from '@/ledger/records';

export const ringName = (tenant: string, visitorId: string) => `${tenant}:${visitorId}`;
export const statsName = (tenant: string, brand: string, slot: string) => `${tenant}:${brand}:${slot}`;
export const liftKey = (tenant: string, brand: string, slot: string) => `lift:${tenant}:${brand}:${slot}`;
/** Phase 3 (doc 22 §12.3): every published snapshot is also archived by version, so a replay can read the one in force. */
export const liftArchiveKey = (tenant: string, brand: string, slot: string, version: number) => `lift/${tenant}/${brand}/${slot}/${version}.json`;

type NS = DurableObjectNamespace | undefined;
async function post(ns: NS, name: string, path: string, body: unknown): Promise<Response | null> {
  if (!ns) return null;
  try {
    const stub = ns.get(ns.idFromName(name));
    return await stub.fetch(`https://learn${path}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  } catch { return null; }
}

/**
 * CW30: the visitor's ring, read on the decision path under a time budget so
 * the fatigue term can never extend a decision by more than `timeoutMs`. Null
 * when the ring is unbound, slow or failing: no penalty, never an error.
 */
export async function readRing(env: Pick<Env, 'DECISION_RING'>, tenant: string, visitorId: string, timeoutMs = 60): Promise<RingEntry[] | null> {
  const ns = env.DECISION_RING;
  if (!ns) return null;
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    const read = ns.get(ns.idFromName(ringName(tenant, visitorId))).fetch('https://learn/recent').then(async (res) => {
      // The ring keeps the full served records; attribution and the fatigue term read them as entries.
      const body = (await res.json()) as { ok?: boolean; ring?: Array<DecisionRecord | RingEntry> };
      return body.ok && Array.isArray(body.ring) ? body.ring.map((r) => ('decision_id' in r ? ringEntryOf(r) : r)) : null;
    });
    const late = new Promise<null>((resolve) => { timer = setTimeout(() => resolve(null), timeoutMs); });
    return await Promise.race([read, late]);
  } catch { return null; } finally { if (timer !== undefined) clearTimeout(timer); }
}

/** CW30: slot → item → times served inside that slot's fatigue window, from the ring entries. */
export function servedCounts(ring: readonly RingEntry[], slots: ReadonlyArray<{ slot: string; fatigue?: { weight: number; windowHours: number } }>, now: number): Record<string, Record<string, number>> {
  const out: Record<string, Record<string, number>> = {};
  for (const s of slots) {
    if (!s.fatigue || s.fatigue.weight <= 0) continue;
    const since = now - s.fatigue.windowHours * 3_600_000;
    const counts: Record<string, number> = {};
    for (const e of ring) if (e.ts >= since && e.ts <= now) counts[e.item] = (counts[e.item] ?? 0) + 1;
    if (Object.keys(counts).length) out[s.slot] = counts;
  }
  return out;
}

export const ringEntryOf = (r: DecisionRecord): RingEntry =>
  ({ id: r.decision_id, ts: r.ts, page: r.page, slot: r.slot, item: r.item_id, session_id: r.session_id, arm: r.arm, cell: r.cell, ...(r.featured_product_ids?.length ? { products: [...r.featured_product_ids] } : {}) });

/** The slot's configuration the statistics object publishes against. */
export interface SlotLearnConfig { reward: RewardType; stats: StatsConfig; /** CW27: absent means unit. */ objective?: 'unit' | 'revenue' | 'margin' }

/** After a decision set is served: the ring gets the full records, each slot's object gets its exposures. */
export async function fanDecisions(env: Pick<Env, 'DECISION_RING' | 'LEARN_STATS'>, set: { tenant: string; brand: string; visitor_id: string; records: DecisionRecord[] }, slotConfig: (slot: string) => SlotLearnConfig): Promise<void> {
  if (set.records.length === 0) return;
  const jobs: Promise<unknown>[] = [
    post(env.DECISION_RING, ringName(set.tenant, set.visitor_id), '/append', { tenant: set.tenant, visitorId: set.visitor_id, records: set.records }),
  ];
  const bySlot = new Map<string, DecisionRecord[]>();
  // Doc 22 §10, absolute: holdout traffic never feeds the statistics. Only the personalized arm's
  // exposures count; the ring still keeps every arm's decisions, for the receipt and the report.
  for (const r of set.records) { if (r.arm === 'personalized') bySlot.set(r.slot, [...(bySlot.get(r.slot) ?? []), r]); }
  for (const [slot, records] of bySlot) {
    jobs.push(post(env.LEARN_STATS, statsName(set.tenant, set.brand, slot), '/exposures', {
      tenant: set.tenant, brand: set.brand, slot, config: slotConfig(slot),
      exposures: records.map((r) => ({ item: r.item_id, cell: r.cell, ts: r.ts })),
    }));
  }
  await Promise.all(jobs.map((j) => j.catch(() => undefined)));
}

/** An outcome to the visitor's ring, which attributes it under the policy and forwards the credits. */
export async function fanOutcome(env: Pick<Env, 'DECISION_RING'>, tenant: string, outcome: OutcomeRecord, policy: AttributionPolicy, brand: string, slotConfig: Record<string, SlotLearnConfig>): Promise<void> {
  await post(env.DECISION_RING, ringName(tenant, outcome.visitor_id), '/outcome', { tenant, brand, outcome, policy, slotConfig });
}
"}

{"path":"src/routes/identity.test.ts","sha256":"b466d97a8d4c16df43251b61370006469aade91ca05b0b2e27cd1c44129d6bda","content":"// src/routes/identity.test.ts
//
// CW25 through the wire, on the session host: a phone and a laptop browse as
// strangers, both sign in to the same account, and the person is the sum. Then
// the rules around the edges: the assertion, the shopper-id refusal, the shared
// computer, detach, history in both formats, and who may ask what.

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import * as jose from 'jose';
import type { Env } from '@/types/env';
import { identityRoutes } from '@/routes/identity';
import { SessionManager } from '@/services/SessionManager';
import { RealtimeSegmentEngine } from '@/services/RealtimeSegmentEngine';
import { FeatureVariableManager } from '@/services/FeatureVariableManager';
import { CDPService } from '@/services/CDPService';
import { DEFAULT_REFLEX_CONFIG, apply, audienceKey, emptyState, snapshot, type ReflexState } from '@/reflex/core';
import { signAssertion } from '@/identity/assertion';
import { shopperIdFor } from '@/identity/shopperId';
import { createCore } from '@/sdk/core';
import { createIdentity } from '@/sdk/identify';
import { memoryHost } from '@/sdk/memoryHost';
import { issueSessionCapability, SHOPPER_HEADER } from '@/identity/sessionCapability';
import { erasureJobKey, ERASURE_STEP_LIMIT } from '@/identity/erase';
import { IdentityStore } from '@/identity/store';
import { ShopperReflex } from '@/durable-objects/ShopperReflex';
import { DecisionRing } from '@/durable-objects/DecisionRing';
import { shopperObjectName } from '@/tenancy/objects';
import { tenantKey } from '@/tenancy/tenant';

class FakeKV {
  store = new Map<string, string>();
  pageSize = 1000;
  async get(key: string, type?: string) { const r = this.store.get(key); return r === undefined ? null : (type === 'json' ? JSON.parse(r) : r); }
  async put(key: string, value: string) { this.store.set(key, value); }
  async delete(key: string) { this.store.delete(key); }
  async list(o?: { prefix?: string; limit?: number; cursor?: string }) {
    const names = [...this.store.keys()].filter(k => k.startsWith(o?.prefix ?? '')).sort();
    const start = Number(o?.cursor ?? 0), end = start + Math.min(this.pageSize, o?.limit ?? 1000);
    return { keys: names.slice(start, end).map(name => ({ name })), list_complete: end >= names.length,
      ...(end < names.length ? { cursor: String(end) } : {}) };
  }
}

const cfg = DEFAULT_REFLEX_CONFIG;
const TABBY = audienceKey('line', 'Tabby');

/** Enough of R2 for the ledger's tombstones: put, get, delete, list by prefix. */
class FakeR2 {
  store = new Map<string, string>();
  versions = new Map<string, number>();
  async put(key: string, body: string, options?: { onlyIf?: Headers }) {
    const current = this.store.has(key) ? 'v' + (this.versions.get(key) ?? 0) : null;
    const condition = options?.onlyIf;
    if ((condition?.get('If-None-Match') === '*' && current !== null)
      || (condition?.has('If-Match') && condition.get('If-Match') !== JSON.stringify(current))) return null;
    this.store.set(key, body); const version = (this.versions.get(key) ?? 0) + 1; this.versions.set(key, version);
    return { etag: 'v' + version };
  }
  async get(key: string) { const v = this.store.get(key); return v === undefined ? null : { text: async () => v, etag: 'v' + (this.versions.get(key) ?? 0) }; }
  async delete(key: string) { this.store.delete(key); }
  async list(o: { prefix: string }) { return { objects: [...this.store.keys()].filter((k) => k.startsWith(o.prefix)).map((key) => ({ key })), truncated: false }; }
}

const mkEnv = (over: Record<string, unknown> = {}): Env => ({
  CACHE: new FakeKV(), SESSIONS: new FakeKV(), STORAGE: new FakeR2(), ENVIRONMENT: 'test', CONNECTOR_MODE: 'mock',
  JWT_SECRET: 'w0202-synthetic-route-signing-material', JWT_ISSUER: 'i', JWT_AUDIENCE: 'a', IDENTITY_SECRETS: 'coach:s3cret', ...over,
} as unknown as Env);
const token = (sub = 'ops') => new jose.SignJWT({ sub }).setProtectedHeader({ alg: 'HS256' }).setIssuedAt().setIssuer('i').setAudience('a').setExpirationTime('5m').sign(new TextEncoder().encode('w0202-synthetic-route-signing-material'));

const browse = (values: string[], at: number): ReflexState => {
  let s = emptyState(cfg);
  values.forEach((v, i) => { s = apply(s, { action: 'product_view', touches: [{ dim: 'line', value: v }] }, at + i * 1000, cfg).state; });
  return s;
};

let env: Env;
let auth: Record<string, string>;
let ownedIds = new Map<string, string>();

async function seedDevice(visitorId: string, sessionId: string, values: string[]) {
  ownedIds.set(visitorId, sessionId);
  const sm = new SessionManager(env);
  // Built a few seconds ago, not at T0: the route merges at Date.now(), and a vector from 2023 is dust by now.
  await sm.createOrUpdateSession(sessionId, visitorId, { reflex: browse(values, Date.now() - 5_000), attributes: { product_views: values.length } });
}

async function call(path: string, init: RequestInit & { json?: unknown } = {}) {
  const headers: Record<string, string> = { ...(init.headers as Record<string, string> ?? {}) };
  let body = init.body;
  if (init.json !== undefined) { headers['Content-Type'] = 'application/json'; body = JSON.stringify(init.json); }
  const res = await identityRoutes.request(path, { ...init, headers, body }, env);
  return { status: res.status, body: (await res.json()) as Record<string, any>, headers: res.headers };
}

async function ownedCall(path: string, init: RequestInit & { json?: unknown }) {
  const visitorId = (init.json as { visitorId?: string })?.visitorId ?? 'vis-00000000-0000-4000-8000-000000000099';
  const subject = /^[A-Za-z0-9_.-]+$/.test(visitorId) ? visitorId : 'vis-00000000-0000-4000-8000-000000000099';
  const session = await issueSessionCapability(env, { tenant: 'coach', subject, sessionId: ownedIds.get(subject) ?? 's-owned-fresh', kind: subject.startsWith('sh_') ? 'recognized' : 'anonymous' });
  return call(path, { ...init, headers: { ...init.headers, [SHOPPER_HEADER]: session.capability } });
}

// Explicit positive-fixture signing only. The SDK transport below never uses this helper.
async function signedCall(path: string, init: RequestInit & { json?: unknown }) {
  const body = init.json as { visitorId: string; accountId: string };
  const exp = Math.floor(Date.now() / 1000) + 120;
  const assertion = await signAssertion('s3cret', 'coach', body.visitorId, body.accountId, exp);
  return ownedCall(path, { ...init, json: { ...body, exp, assertion } });
}

beforeEach(async () => {
  env = mkEnv();
  ownedIds = new Map();
  auth = { Authorization: `Bearer ${await token()}` };
});
afterEach(() => { vi.restoreAllMocks(); });

describe('the link, on the session host', () => {
  it('a phone signs in: the response names the person, sets the cookie, and the old cookie reads the person', async () => {
    await seedDevice('vis-00000000-0000-4000-8000-000000000001', 's-phone', ['Tabby', 'Tabby', 'Tabby']);
    const r = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-1001' } });
    expect(r.status).toBe(200);
    expect(r.body.outcome).toBe('linked');
    expect(r.body.assurance).toBe('signed');
    expect(r.body.shopperId).toBe(await shopperIdFor(env, 'coach', 'acct-1001'));
    expect(r.body.carry).toBe(r.body.shopperId);
    expect(r.body.audiences).toContain(TABBY);
    const cookies = r.headers.get('set-cookie') ?? '';
    expect(cookies).toContain('opt_session_id=');
    expect(cookies).toContain(`opt_user_id=${r.body.shopperId}`);
    expect(cookies).not.toContain('opt_session_id=s-phone');

    const sm = new SessionManager(env);
    expect((await sm.getSession('s-phone'))?.userId).toBe(r.body.shopperId);
  });

  it('a laptop signs in to the same account: cross-device, the person is the sum', async () => {
    await seedDevice('vis-00000000-0000-4000-8000-000000000001', 's-phone', ['Tabby', 'Tabby']);
    await seedDevice('vis-00000000-0000-4000-8000-000000000002', 's-laptop', ['Rogue', 'Rogue', 'Tabby']);
    const a = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-1001' } });
    const b = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000002', accountId: 'acct-1001', source: 'checkout' } });
    expect(b.body.shopperId).toBe(a.body.shopperId);
    expect(b.body.outcome).toBe('linked');

    const sm = new SessionManager(env);
    const person = await sm.getSessionByUserId(b.body.shopperId);
    const snap = snapshot(person!.reflex!, Date.now(), cfg);
    expect(Object.keys(snap.dims.line).sort()).toEqual(['Rogue', 'Tabby']);
    expect(person!.attributes.product_views).toBe(5);
    expect(person!.metadata.visitCount).toBe(2);
    // Either browser resolves to the person.
    expect((await sm.getSession('s-phone'))?.userId).toBe(b.body.shopperId);
    expect((await sm.getSession('s-laptop'))?.userId).toBe(b.body.shopperId);
  });

  it('the old anonymous grant cannot follow the linked browser into the person', async () => {
    await seedDevice('vis-00000000-0000-4000-8000-000000000001', 's-phone', ['Tabby']);
    const a = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-1001' } });
    const b = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-1001' } });
    expect(b.status).toBe(401);
    expect((await new SessionManager(env).getSessionByUserId(a.body.shopperId))!.attributes.product_views).toBe(1);
  });

  it('a shared computer requires detach and a newly owned browser before linking another account', async () => {
    await seedDevice('vis-00000000-0000-4000-8000-000000000001', 's-phone', ['Tabby', 'Tabby', 'Tabby']);
    const first = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-1001' } });
    const refused = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-2002' } });
    expect(refused.status).toBe(401);
    const detached = await call('/coach/identity/detach', { method: 'POST', headers: { [SHOPPER_HEADER]: first.body.session.capability } });
    const fresh = detached.body.session;
    const exp = Math.floor(Date.now() / 1000) + 120;
    const assertion = await signAssertion('s3cret', 'coach', fresh.subject, 'acct-2002', exp);
    const second = await call('/coach/identity/link', { method: 'POST', headers: { [SHOPPER_HEADER]: fresh.capability }, json: { visitorId: fresh.subject, accountId: 'acct-2002', exp, assertion } });
    expect(second.status).toBe(200); expect(second.body.shopperId).not.toBe(first.body.shopperId); expect(second.body.audiences).toEqual([]);
    expect((await new SessionManager(env).getSessionByUserId(first.body.shopperId))?.reflex?.audiences).toContain(TABBY);
  });

  it('refuses to link a browser that already carries a shopper id', async () => {
    const sh = await shopperIdFor(env, 'coach', 'acct-1001');
    const r = await ownedCall('/coach/identity/link', { method: 'POST', json: { visitorId: sh, accountId: 'acct-2002' } });
    expect(r.status).toBe(409);
  });

  it('a browser with no session yet links fine: the person starts empty', async () => {
    const r = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000004', accountId: 'acct-1001' } });
    expect(r.status).toBe(200);
    expect(r.body.audiences).toEqual([]);
    const sm = new SessionManager(env);
    expect(await sm.resolveSessionIdByUserId('vis-00000000-0000-4000-8000-000000000004')).toBe(await sm.resolveSessionIdByUserId(r.body.shopperId));
  });

  it('validates the body and the tenant', async () => {
    expect((await ownedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000005' } })).status).toBe(400);
    expect((await ownedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 't:kate-spade:vis-00000000-0000-4000-8000-000000000005', accountId: 'a' } })).status).toBe(401);
    expect((await ownedCall('/not a tenant/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000005', accountId: 'a' } })).status).toBe(401);
  });
});

describe('the assertion, when the tenant has a secret', () => {
  beforeEach(() => { env = mkEnv({ IDENTITY_SECRETS: 'coach:s3cret' }); });

  it('refuses an unsigned link, accepts the site-signed one, and records signed assurance', async () => {
    const unsigned = await ownedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000005', accountId: 'acct-1001' } });
    expect(unsigned.status).toBe(401);
    const exp = Math.floor(Date.now() / 1000) + 120;
    const assertion = await signAssertion('s3cret', 'coach', 'vis-00000000-0000-4000-8000-000000000005', 'acct-1001', exp);
    const signed = await ownedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000005', accountId: 'acct-1001', exp, assertion } });
    expect(signed.status).toBe(200);
    expect(signed.body.assurance).toBe('signed');
