describe('W06.01 durable local erasure retry', () => {
  function destinations() {
    const calls: string[] = [];
    const fail = { object: false, ring: false };
    function namespace(kind: 'object' | 'ring') {
      const items = new Map<string, { data: Map<string, unknown>; object: { fetch(request: Request): Promise<Response> } }>();
      function open(name: string) {
        let item = items.get(name);
        if (!item) {
          const data = new Map<string, unknown>();
          const state = { id: name, getWebSockets: () => [], storage: {
            get: async (key: string | string[]) => Array.isArray(key) ? new Map(key.map(k => [k, data.get(k)])) : data.get(key),
            put: async (key: string, value: unknown) => { data.set(key, value); }, deleteAll: async () => { data.clear(); },
            getAlarm: async () => null, setAlarm: async () => {},
          } } as unknown as DurableObjectState;
          item = { data, object: kind === 'object' ? new ShopperReflex(state, env) : new DecisionRing(state, env) }; items.set(name, item);
        }
        return item;
      }
      const ns = { idFromName: (n: string) => n, get: (name: string) => ({ fetch: async (input: RequestInfo | URL, init?: RequestInit) => {
        calls.push(kind + ':' + name);
        if (fail[kind]) return Response.json({ ok: true }); // Deliberately incomplete ring acknowledgment; object failure uses HTTP error.
        return open(name).object.fetch(new Request(input, init));
      } }) } as unknown as DurableObjectNamespace;
      return { ns, open, items };
    }
